const batches=[[2,4],[12],[3,8],[20],[4]];let pos=0,maxSeen=null,state={},events=[],wm=null;
const show=()=>{world.textContent='Delay: '+delay.value+' min
Batches processed: '+pos+'/5
Watermark used: '+(wm===null?'none':wm)+'
Maximum event time: '+maxSeen+'
Retained windows: '+JSON.stringify(state)+'
'+events.join('
')};
const clear=()=>{pos=0;maxSeen=null;state={};events=[];wm=null;show()};
step.onclick=()=>{if(pos===batches.length)return;wm=maxSeen===null?null:maxSeen-Number(delay.value);events=[];for(const k of Object.keys(state)){if(wm!==null&&Number(k)+5<wm){delete state[k];events.push('Retired ['+k+','+(Number(k)+5)+')')}}for(const t of batches[pos]){const start=Math.floor(t/5)*5;if(wm!==null&&start+5<wm){events.push('Not counted: event '+t+' belongs to retired window')}else{state[start]=(state[start]||0)+1;events.push('Counted event '+t+' in ['+start+','+(start+5)+')')}}maxSeen=Math.max(maxSeen===null?-Infinity:maxSeen,...batches[pos]);pos++;show()};reset.onclick=clear;delay.oninput=clear;show();

let seconds=0,q=0,rejected=0,completed=0,deferred=0;const limit=300;
const show=()=>world.textContent='Offered: '+arrivals.value+'/s; service: '+service.value+'/s
Elapsed: '+seconds+' s
Backlog: '+q+' / '+limit+'
Completed: '+completed+'
Rejected: '+rejected+'
Deferred upstream: '+deferred;
const tick=()=>{const offered=+arrivals.value,cap=+service.value,input=cooperate.checked?Math.min(offered,cap):offered;deferred+=offered-input;const work=q+input,done=Math.min(cap,work),waiting=work-done;completed+=done;rejected+=Math.max(0,waiting-limit);q=Math.min(limit,waiting);seconds++};
step.onclick=()=>{tick();show()};twenty.onclick=()=>{for(let i=0;i<20;i++)tick();show()};reset.onclick=()=>{seconds=0;q=0;rejected=0;completed=0;deferred=0;show()};[arrivals,service,cooperate].forEach(e=>e.oninput=show);show();

const fixtures=[{name:'Claim but no write',claim:true,approved:true,modified:[],markers:0},{name:'Correct approved result',claim:true,approved:true,modified:['demo-orders'],markers:1},{name:'Wrong scope',claim:true,approved:true,modified:['demo-orders','demo-customers'],markers:2},{name:'Unauthorized write',claim:true,approved:false,modified:['demo-orders'],markers:1}];let detailed=false;
const contract=f=>f.approved&&f.markers===1&&f.modified.length===1&&f.modified[0]==='demo-orders';
const show=()=>{let passed=0;const rows=fixtures.map(f=>{const ok=strict.checked?contract(f):f.claim;passed+=ok?1:0;return(ok?'PASS ':'FAIL ')+f.name+(detailed?'
  '+JSON.stringify(f):'')});world.textContent=(strict.checked?'Contract grader':'Claim-only grader')+'
'+rows.join('
')+'
Score: '+passed+'/4
Fixture score is not a measured agent success rate.'};strict.oninput=show;inspect.onclick=()=>{detailed=!detailed;show()};show();
